    from collections import Counter,deque
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    res=[r[:] for r in g]; seen=set()
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v==bg or (r,c) in seen: continue
            q=deque([(r,c)]); comp={(r,c)}; seen.add((r,c))
            while q:
                x,y=q.popleft()
                for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<H and 0<=b<W and g[a][b]==v and (a,b) not in comp:
                        q.append((a,b)); comp.add((a,b))
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            icnt=sum(1 for a in range(r0+1,r1) for b in range(c0+1,c1) if g[a][b]==bg)
            edge=(r0==0 or r1==H-1 or c0==0 or c1==W-1)
            fill=7 if not edge else 2
            for a in range(r0+1,r1):
                for b in range(c0+1,c1):
                    if g[a][b]==bg: res[a][b]=fill
    return res
